        for c in range(w - 1):
            if all(grid[rr][cc] == 7 for rr in (r, r+1) for cc in (c, c+1)):
                # candidate 7 block only when its four cells form the compact motif
                # and it is the right-lower instance of that color
                if r >= h // 2:
                    for rr in (r, r+1):
                        for cc in (c, c+1):
